  const R=24,T=18,rowH=Math.max(18,Math.min(30,230/d.length)),W=id==="chFn"?1260:620,ph=rowH*d.length,H=T+ph+6,pw=W-L-R;
  const mx=axisMax(Math.max(1,...d.map(x=>x.a))),X=v=>L+pw*v/mx,bh=(rowH-4)/3;let s="";
