  d.forEach((x,k)=>{const y=T+k*rowH+2;
    [["a","#2E75B6"],["c","#548235"],["od","#C00000"]].forEach(([f,c],j)=>{const w=X(x[f])-L;if(w>0)s+=`<rect x="${L}" y="${y+j*bh}" width="${w}" height="${bh-1}" fill="${c}" rx="1.5"/>`});
    s+=`<text x="${L-6}" y="${y+rowH/2+2}" font-size="10.5" fill="#1a1a1a" text-anchor="end">${esc(x.n)}</text>`;
    s+=`<rect x="0" y="${y-2}" width="${W}" height="${rowH}" fill="transparent" data-tip="${esc(`<b>${esc(x.n)}</b>${row("#2E75B6","Assigned",x.a)}${row("#548235","Completed",x.c)}${row("#C00000","Overdue",x.od)}${row("#fff","Completion rate",pc(x.rate))}`)}"/>`});
