// ---------- import / export ----------
const HEAD=["SL.","Task","Assigned Date","Assigned By","Job Function","Tentative Date to Complete","Remaining Days","Completion Date","Assigned To 1","Assigned To 2","Assigned To 3","Priority Setting","Completion Percentage","Remarks"];
const csvq=v=>{v=String(v??"");if(/^[=+\-@\t\r]/.test(v)&&!/^-?\d+%?$/.test(v))v="'"+v;return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v};
function toCSV(){return "﻿"+[HEAD,...S.tasks.map((t,i)=>{const r=C.rows[i];return [r.valid?i+1:"",t.task,t.ad,t.by,t.fn,t.due,r.remain,t.cd,t.a1,t.a2,t.a3,t.pr,(+t.pct||0)+"%",t.rem]})].map(a=>a.map(csvq).join(",")).join("\r\n")}
function parseCSV(s,d=","){s=s.replace(/^﻿/,"");const out=[];let row=[],cur="",q=false;
  for(let i=0;i<s.length;i++){const c=s[i];if(q){if(c==='"'){if(s[i+1]==='"'){cur+='"';i++}else q=false}else cur+=c}
   else if(c==='"')q=true;else if(c===d){row.push(cur);cur=""}else if(c==="\n"||c==="\r"){if(c==="\r"&&s[i+1]==="\n")i++;row.push(cur);out.push(row);row=[];cur=""}else cur+=c}
  if(cur!==""||row.length){row.push(cur);out.push(row)}return out}
// order: "dmy" (default) or "mdy", for dates like 05/11/2026
function normDate(v,order){v=(v||"").trim();if(!v)return"";if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;
  if(/^\d{5}(\.\d+)?$/.test(v)){const n=Math.floor(+v);if(n>20000&&n<80000)return new Date(Date.UTC(1899,11,30)+n*MS).toISOString().slice(0,10)} // Excel date number
  let m=/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/.exec(v);if(m){let y=+m[3];if(y<100)y+=2000;const [d,mo]=order==="mdy"?[+m[2],+m[1]]:[+m[1],+m[2]];
    if(mo<1||mo>12||d<1||d>31)return"";return y+"-"+String(mo).padStart(2,"0")+"-"+String(d).padStart(2,"0")}
  m=/^(\d{1,2})[\s\-]([A-Za-z]{3})[a-z]*[\s\-](\d{2,4})$/.exec(v);if(m){let y=+m[3];if(y<100)y+=2000;const mi=MON.findIndex(x=>x.toLowerCase()===m[2].toLowerCase());if(mi>=0)return y+"-"+String(mi+1).padStart(2,"0")+"-"+String(m[1]).padStart(2,"0")}
  const d=new Date(v);return isNaN(d)?"":d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
function download(name,text,type){
  try{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.appendChild(a);a.click();a.remove();}catch(e){}
  // fallback for viewers that block downloads
  openModal(name,"If the file did not download (some web viewers block downloads), copy the text below and save it as "+name+".",text);
}
function openModal(t,n,x){mTitle.textContent=t;mNote.textContent=n;mText.value=x;modal.style.display="flex"}
mClose.onclick=()=>modal.style.display="none";
mCopy.onclick=async()=>{try{await navigator.clipboard.writeText(mText.value);mCopy.textContent="Copied ✓"}catch(e){mText.select();mCopy.textContent="Press Ctrl+C"}setTimeout(()=>mCopy.textContent="Copy",1800)};
expCsv.onclick=()=>download("HR_Task_Tracker_"+todayStr()+".csv",toCSV(),"text/csv");
expJson.onclick=()=>download("HR_Task_Tracker_Backup_"+todayStr()+".json",JSON.stringify(S,null,1),"application/json");
// Headings the CSV reader understands: this app's own export, and the Excel "Task Tracker" sheet.
const CSV_COLS={task:["Task","Task Name"],ad:["Assigned Date","Started Date","Start Date"],by:["Assigned By"],fn:["Job Function","Type of Job/Function","Function"],
  due:["Tentative Date to Complete","Tentative Date to be Completed","Due Date"],cd:["Completion Date","Completed Date"],
  a1:["Assigned To 1"],a2:["Assigned To 2"],a3:["Assigned To 3"],pr:["Priority Setting","Priority"],pct:["Completion Percentage","Completion %"],rem:["Remarks","Any Remarks"]};
const hnorm=s=>String(s).trim().toLowerCase().replace(/\s+/g," ");
// day/month order of the file's dates; when every date fits both, Excel used this computer's setting
function dateOrder(vals){let dmy=0,mdy=0;
  for(const v of vals){const m=/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.]\d{2,4}$/.exec(v);if(!m)continue;if(+m[1]>12)dmy++;else if(+m[2]>12)mdy++}
  if(dmy||mdy)return dmy>=mdy?"dmy":"mdy";
  try{const p=new Intl.DateTimeFormat().formatToParts(new Date(2026,0,15));return p.findIndex(x=>x.type==="month")<p.findIndex(x=>x.type==="day")?"mdy":"dmy"}catch(e){return"dmy"}}
// CSV text → tasks, or null when no heading row is found. Title rows above the headings are skipped.
function csvTasks(s){s=s.replace(/^﻿/,"");
  for(const d of [",",";","\t"]){const t=rowsTasks(parseCSV(s,d));if(t)return t}
  return null}
// table rows (arrays of cell text) → tasks, or null when no heading row is found
function rowsTasks(rows){rows=rows.filter(r=>r.some(x=>x.trim()!==""));
  const hi=rows.slice(0,15).findIndex(r=>r.some(x=>CSV_COLS.task.some(n=>hnorm(n)===hnorm(x))));if(hi<0)return null;
  const h=rows[hi].map(hnorm),ix={};for(const k in CSV_COLS)ix[k]=h.findIndex(x=>CSV_COLS[k].some(n=>hnorm(n)===x));
  const body=rows.slice(hi+1),g=(r,k)=>ix[k]>=0?(r[ix[k]]||"").trim().replace(/^'(?=[=+\-@])/,""):"";
  const order=dateOrder(body.flatMap(r=>[g(r,"ad"),g(r,"due"),g(r,"cd")]));
  return cleanTasks(body.map(r=>{let p=g(r,"pct").replace("%","");p=p===""?0:+p;if(p>0&&p<=1&&g(r,"pct").indexOf("%")<0)p=p*100;
    const prRaw=g(r,"pr").toLowerCase()==="critical"?"urgent":g(r,"pr").toLowerCase();const pr=PRIOS.find(x=>x.toLowerCase()===prRaw)||"";
    return {task:g(r,"task"),ad:normDate(g(r,"ad"),order),by:g(r,"by"),fn:g(r,"fn"),due:normDate(g(r,"due"),order),cd:normDate(g(r,"cd"),order),a1:g(r,"a1"),a2:g(r,"a2"),a3:g(r,"a3"),pr,pct:Math.round(Math.max(0,Math.min(100,p||0))),rem:g(r,"rem")}}))}

// ---------- Excel .xlsx reading (no library: an .xlsx is a zip of XML files) ----------
// zip bytes → function(name) giving that entry's text, or null when it is missing
function unzip(buf){const v=new DataView(buf),u8=new Uint8Array(buf),files={},td=new TextDecoder();
  let e=buf.byteLength-22;while(e>=0&&v.getUint32(e,true)!==0x06054b50)e--;if(e<0)throw new Error("not a zip file");
  let p=v.getUint32(e+16,true);const n=v.getUint16(e+10,true);
  for(let k=0;k<n&&v.getUint32(p,true)===0x02014b50;k++){const nl=v.getUint16(p+28,true);
    files[td.decode(u8.subarray(p+46,p+46+nl))]={method:v.getUint16(p+10,true),size:v.getUint32(p+20,true),off:v.getUint32(p+42,true)};
    p+=46+nl+v.getUint16(p+30,true)+v.getUint16(p+32,true)}
  return async name=>{const f=files[name];if(!f)return null;
    const s=f.off+30+v.getUint16(f.off+26,true)+v.getUint16(f.off+28,true),data=u8.subarray(s,s+f.size);
    if(f.method===0)return td.decode(data);if(f.method!==8)throw new Error("unsupported zip compression");
    return new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream("deflate-raw"))).text()}}
const xmlDoc=s=>new DOMParser().parseFromString(s,"application/xml");
const xEls=(n,tag)=>[...n.getElementsByTagNameNS("*",tag)];
const colNum=ref=>{let c=0;for(const ch of ref.replace(/\d+$/,""))c=c*26+ch.charCodeAt(0)-64;return c-1};
// .xlsx bytes → [{name, rows}] for every worksheet, rows being arrays of cell text
async function xlsxSheets(buf){const get=unzip(buf);
  const ss=await get("xl/sharedStrings.xml"),strs=ss?xEls(xmlDoc(ss),"si").map(si=>xEls(si,"t").filter(t=>t.parentNode.localName!=="rPh").map(t=>t.textContent).join("")):[];
  const rels={};xEls(xmlDoc(await get("xl/_rels/workbook.xml.rels")||"<r/>"),"Relationship").forEach(r=>rels[r.getAttribute("Id")]=r.getAttribute("Target"));
  const out=[];
  for(const sh of xEls(xmlDoc(await get("xl/workbook.xml")||"<r/>"),"sheet")){
    const rid=[...sh.attributes].find(a=>a.localName==="id"&&a.prefix)?.value,tg=rels[rid];if(!tg)continue;
    const x=await get(tg.startsWith("/")?tg.slice(1):"xl/"+tg.replace(/^\.\//,""));if(!x)continue;
    const rows=xEls(xmlDoc(x),"row").map(row=>{const r=[];let next=0;
      for(const c of xEls(row,"c")){const ref=c.getAttribute("r"),i=ref?colNum(ref):next;next=i+1;
        const t=c.getAttribute("t"),vEl=xEls(c,"v")[0],val=vEl?vEl.textContent:"";
        r[i]=t==="s"?(strs[+val]??""):t==="inlineStr"?xEls(c,"t").map(e=>e.textContent).join(""):t==="b"?(val==="1"?"TRUE":"FALSE"):t==="e"?"":val}
      return Array.from(r,x=>x??"")});
    out.push({name:sh.getAttribute("name")||"",rows})}
  return out}
// the tasks of the first sheet that has tracker headings (a sheet named like "Task Tracker" is tried first)
async function xlsxTasks(buf){const sheets=await xlsxSheets(buf);
  sheets.sort((a,b)=>(/task|tracker/i.test(b.name)?1:0)-(/task|tracker/i.test(a.name)?1:0));
  let found=null;for(const s of sheets){const t=rowsTasks(s.rows);if(t&&t.length)return t;if(t)found=t}
  return found}

// CSV or Excel file → tasks; tells the person what went wrong when it cannot read the file
function readCsvFile(e,then){const f=e.target.files[0];e.target.value="";if(!f)return;
  f.arrayBuffer().then(async buf=>{const b=new Uint8Array(buf,0,Math.min(4,buf.byteLength));
    if(b[0]===0xD0&&b[1]===0xCF){toast("This is an old .xls file. In Excel use File › Save As › Excel Workbook (.xlsx) or CSV, then upload that.");return}
    const isZip=b[0]===0x50&&b[1]===0x4B;let tasks;
    try{tasks=isZip?await xlsxTasks(buf):csvTasks(new TextDecoder().decode(buf))}
    catch(err){console.error(err);toast(isZip?"Could not read this Excel file. If it has a password, remove it, or save the sheet as CSV.":"Could not read this file.");return}
    if(!tasks){toast(isZip?"No sheet in this Excel file has tracker headings (e.g. 'Task' or 'Task Name').":"This CSV has no tracker headings (e.g. 'Task' or 'Task Name').");return}
    if(!tasks.length){toast("No tasks found in this file.");return}
    then(tasks,newNames(tasks),f.name)})}
// names in the tasks that the Lists don't have yet, kept exactly as spelled in the file
function newNames(tasks){const out={members:[],assigners:[],functions:[]};
  const add=(k,v)=>{if(!v)return;const l=v.toLowerCase();if(S[k].some(x=>x.toLowerCase()===l)||out[k].some(x=>x.toLowerCase()===l))return;out[k].push(v)};
  tasks.forEach(t=>{add("members",t.a1);add("members",t.a2);add("members",t.a3);add("assigners",t.by);add("functions",t.fn)});return out}
const namesNote=nn=>{const n=nn.members.length+nn.assigners.length+nn.functions.length;return n?` ${n} new name${n===1?"":"s"} from the file will be added to the Lists.`:""};
impCsv.onchange=e=>readCsvFile(e,(tasks,nn)=>{const p={tasks};for(const k in nn)if(nn[k].length)p[k]=[...S[k],...nn[k]];
  askConfirm("Import file?",`All ${S.tasks.length} current tasks will be replaced for everyone by ${tasks.length} tasks from this file.${namesNote(nn)}`,"Replace",()=>replaceAll(p,`Imported ${tasks.length} tasks (replaced existing).`))});
// Upload CSV / Excel (New Task form): adds the file's tasks to the ones already there
fCsv.onchange=e=>readCsvFile(e,(tasks,nn,name)=>askConfirm("Upload tasks from file?",`${tasks.length} task${tasks.length===1?"":"s"} from “${name}” will be added for everyone. Existing tasks stay as they are.${namesNote(nn)}`,"Upload",()=>uploadTasks(tasks,nn)));
async function uploadTasks(tasks,nn){
  const rows=Object.entries(nn).flatMap(([kind,a])=>a.map(name=>({kind,name})));let listFail=false;
  const r=await run(async()=>{const a=await dbInsertMany(tasks);let l=[];try{l=await dbListAddMany(rows)}catch(e){console.error(e);listFail=true}return {a,l}});
  if(!r.ok)return;
  closeForm();if(location.hash!=="#tracker")location.hash="#tracker";await refresh(true);
  const ids=r.v.a.map(t=>t.id),lids=r.v.l.map(x=>x.id);
  undo=()=>run(async()=>{await dbDeleteMany("tasks",ids);if(lids.length)await dbDeleteMany("list_items",lids)});
  toast(`${ids.length} task${ids.length===1?"":"s"} added from the file.`+(lids.length?` ${lids.length} new name${lids.length===1?"":"s"} added to Lists.`:"")+(listFail?" Some names could not be added to Lists.":""),true)}
async function replaceAll(p,msg){const old={};for(const k in p)old[k]=k==="reportDate"?S[k]:JSON.parse(JSON.stringify(S[k]));
  const r=await run(()=>dbReplace(p));if(!r.ok)return;
  await refresh(true);undo=()=>run(()=>dbReplace(old));toast(msg,true)}
impJson.onchange=e=>{const f=e.target.files[0];if(!f)return;f.text().then(s=>{let p;try{const j=JSON.parse(s);if(!Array.isArray(j.tasks))throw 0;
    p={tasks:cleanTasks(j.tasks),reportDate:normDate(String(j.reportDate||""))};for(const k of ["members","assigners","functions"])if(Array.isArray(j[k]))p[k]=cleanNames(j[k])}catch(x){toast("That file is not a valid tracker backup.");return}
  askConfirm("Restore backup?",`All ${S.tasks.length} current tasks and the lists will be replaced for everyone by the ${p.tasks.length} tasks in this backup.`,"Restore",()=>replaceAll(p,"Backup restored."))});e.target.value=""};


// ---------- list view (software-style) ----------
let view="list",sortK="sl",sortD=1,stF="",page=0;const PAGE=25;
const COLS=[["sl","SL.",44],["task","Task",260],["status","Status",96],["ad","Assigned Date",100],["by","Assigned By",140],["fn","Job Function",140],["due","Tentative Date to Complete",110],["remain","Remaining Days",80],["cd","Completion Date",100],["a1","Assigned To 1",125],["a2","Assigned To 2",125],["a3","Assigned To 3",125],["pr","Priority",80],["pct","Completion %",110],["rem","Remarks",150],["",'Actions',96]];
function sortVal(r,k){const t=r.t;switch(k){case"sl":return r.i;case"remain":return r.remain==="Done"?1e9:r.remain===""?1e9+1:r.remain;case"pct":return r.cp;case"pr":return PRIOS.indexOf(t.pr)<0?9:PRIOS.indexOf(t.pr);case"status":return STATUSES.indexOf(r.status);default:return String(t[k]||"").toLowerCase()||"￿"}}
function renderList(){
  const q=document.getElementById("search").value.trim().toLowerCase(),fp=lfPri.value,fm=lfMem.value,ff=lfFn.value;
  let rows=C.rows.filter(r=>r.valid||!r.t.task);
  const base=rows.filter(r=>(!q||[r.t.task,r.t.by,r.t.fn,r.t.a1,r.t.a2,r.t.a3,r.t.rem,r.t.pr].join(" ").toLowerCase().includes(q))&&(!fp||r.t.pr===fp)&&(!fm||[r.t.a1,r.t.a2,r.t.a3].includes(fm))&&(!ff||r.t.fn===ff));
  const cnt=s=>base.filter(r=>r.status===s).length;
  counts.innerHTML=[["","All",base.length],...STATUSES.map(s=>[s,s,cnt(s)])].map(([v,l,n])=>`<button data-s="${v}" class="${stF===v?"on":""}">${l}<b>${n}</b></button>`).join("");
  rows=base.filter(r=>!stF||r.status===stF);
  rows.sort((a,b)=>{const x=sortVal(a,sortK),y=sortVal(b,sortK);return (x<y?-1:x>y?1:a.i-b.i)*sortD});
  const pages=Math.max(1,Math.ceil(rows.length/PAGE));if(page>=pages)page=pages-1;
  const pr=rows.slice(page*PAGE,page*PAGE+PAGE);
  lt.querySelector("thead").innerHTML="<tr>"+COLS.map(([k,l,w])=>`<th style="min-width:${w}px" ${k?`data-k="${k}"`:'class="ns"'}>${l}${k===sortK?`<span class="ar">${sortD>0?"▲":"▼"}</span>`:""}</th>`).join("")+"</tr>";
  lt.querySelector("tbody").innerHTML=pr.map(r=>{const t=r.t;return `<tr data-id="${esc(t.id)}">
   <td class="f" style="background:var(--grey);font-weight:700">${r.valid?r.i+1:""}</td><td class="l"><b style="font-weight:600">${esc(t.task)||'<i style="color:#8c8c8c">(no task text)</i>'}</b></td><td>${r.status?`<span class="badge b-${r.status.replace(" ","")}">${r.status}</span>`:""}</td>
   <td>${fmtD(t.ad)}</td><td>${esc(t.by)}</td><td>${esc(t.fn)}</td><td>${fmtD(t.due)}</td><td class="${remainCls(r.remain)}" style="font-weight:700">${r.remain}</td><td>${fmtD(t.cd)}</td>
   <td>${esc(t.a1)}</td><td>${esc(t.a2)}</td><td>${esc(t.a3)}</td><td class="p-${esc(t.pr)}">${esc(t.pr)}</td>
   <td><div style="display:flex;gap:6px;align-items:center"><div class="pbar" style="flex:1"><span style="width:${r.cp}%;background:${r.done?"#548235":"#2E75B6"}"></span></div><span style="width:34px;text-align:right">${r.cp}%</span></div></td>
   <td class="l" style="color:#595959">${esc(t.rem)}</td>
   <td><div class="act"><button class="ed" title="Edit">✎</button>${r.done?"":'<button class="ok" title="Mark complete">✓</button>'}<button class="rm" title="Delete">🗑</button></div></td></tr>`}).join("")||`<tr><td colspan="${COLS.length}" class="empty" style="cursor:default">No tasks found. Click “+ New Task” to add one.</td></tr>`;
  pager.innerHTML=rows.length>PAGE?`<span>Showing ${page*PAGE+1}–${Math.min(rows.length,(page+1)*PAGE)} of ${rows.length}</span><button class="btn" data-p="-1" ${page?"":"disabled"}>‹ Prev</button><span>Page ${page+1} / ${pages}</span><button class="btn" data-p="1" ${page<pages-1?"":"disabled"}>Next ›</button>`:`<span>${rows.length} task${rows.length===1?"":"s"}</span>`;
}
function renderTracker(){
  listView.style.display=view==="list"?"":"none";sheetView.style.display=view==="sheet"?"":"none";
  viewSeg.querySelectorAll("button").forEach(b=>b.classList.toggle("on",b.dataset.v===view));
  lfMem.innerHTML='<option value="">All team members</option>'+S.members.filter(Boolean).map(m=>`<option${m===lfMem.dataset.v?" selected":""}>${esc(m)}</option>`).join("");
  lfFn.innerHTML='<option value="">All job functions</option>'+S.functions.filter(Boolean).map(m=>`<option${m===lfFn.dataset.v?" selected":""}>${esc(m)}</option>`).join("");
  if(view==="list")renderList();else renderSheet();
}
lfMem.onchange=()=>{lfMem.dataset.v=lfMem.value;page=0;renderTracker()};lfPri.onchange=()=>{page=0;renderTracker()};lfFn.onchange=()=>{lfFn.dataset.v=lfFn.value;page=0;renderTracker()};
viewSeg.onclick=e=>{const v=e.target.closest("button")?.dataset.v;if(!v)return;view=v;try{localStorage.setItem(KEY+".view",v)}catch(x){}renderTracker()};
try{view=localStorage.getItem(KEY+".view")||"list"}catch(x){}
counts.onclick=e=>{const b=e.target.closest("button");if(!b)return;stF=b.dataset.s;page=0;renderList()};
pager.onclick=e=>{const p=e.target.closest("button")?.dataset.p;if(!p)return;page+=+p;renderList()};
lt.querySelector("thead").onclick=e=>{const k=e.target.closest("th")?.dataset.k;if(!k)return;if(sortK===k)sortD=-sortD;else{sortK=k;sortD=1}renderList()};
lt.querySelector("tbody").onclick=e=>{const tr=e.target.closest("tr[data-id]");if(!tr)return;const id=tr.dataset.id;
  if(e.target.closest(".ok")){markDone(id);return}if(e.target.closest(".rm")){askDelete(id);return}openForm(id)};
document.addEventListener("click",e=>{const tr=e.target.closest("tr.ovr");if(tr)openForm(tr.dataset.id)});
async function patchTask(id,p,msg){const t=taskById(id);if(!t)return false;const old={};for(const k in p)old[k]=t[k];
  const r=await run(()=>dbPatch(id,p));if(!r.ok)return false;
  putTask(r.v);undo=()=>run(()=>dbPatch(id,old));compute();hdr();refreshCurrent();toast(msg,true);return true}
function markDone(id){const t=taskById(id);if(!t)return;const p={pct:100};if(!t.cd)p.cd=C.rdS;patchTask(id,p,`Marked complete: “${t.task.slice(0,40)}”`)}
let cCb=null;
function askConfirm(title,msg,btn,cb){cTitle.textContent=title;cMsg.textContent=msg;cYes.textContent=btn;confirm_.style.display="flex";cYes.focus();cCb=cb}
function askDelete(id,after){const t=taskById(id);if(!t)return;askConfirm("Delete this task?",`“${t.task.slice(0,90)}” will be removed for everyone. You can undo straight after.`,"Delete",()=>removeTask(id,after))}
const confirm_=document.getElementById("confirm");
cNo.onclick=()=>{confirm_.style.display="none";cCb=null};cYes.onclick=()=>{confirm_.style.display="none";const f=cCb;cCb=null;if(f)f()};

// ---------- entry form ----------
let fId=null,fBase=null,fBusy=false,fPr="";const fEl=id=>document.getElementById(id);
function opts(sel,arr,cur,ph){const list=arr.filter(Boolean);if(cur&&!list.includes(cur))list.push(cur);sel.innerHTML=`<option value="">${ph}</option>`+list.map(v=>`<option${v===cur?" selected":""}>${esc(v)}</option>`).join("")}
function openForm(id){
  if(!loaded)return;const cur=id===null?null:taskById(id);if(id!==null&&!cur)return;
  fId=id;const isEdit=!!cur,t=cur?{...cur}:{...blank(),ad:C.rdS};fBase=t;
  fEl("fTitle").textContent=isEdit?`Edit Task  #${S.tasks.indexOf(cur)+1}`:"New Task";
  f_task.value=t.task;f_ad.value=t.ad;f_due.value=t.due;f_cd.value=t.cd;f_rem2.value=t.rem;
  opts(f_by,S.assigners,t.by,"— Select —");opts(f_fn,S.functions,t.fn,"— Select —");opts(f_a1,S.members,t.a1,"— Select —");opts(f_a2,S.members,t.a2,"— None —");opts(f_a3,S.members,t.a3,"— None —");
  setPr(t.pr||"Medium");f_pct.value=+t.pct||0;f_pctR.value=+t.pct||0;
  fDel.style.display=isEdit?"":"none";fSaveNew.style.display=isEdit?"none":"";fUp.style.display=isEdit?"none":"";
  fMeta.textContent=isEdit?[t.created?"Created "+new Date(t.created).toLocaleString():"",t.updated?"Updated "+new Date(t.updated).toLocaleString():""].filter(Boolean).join("  •  "):"Fields marked * are required";
  document.querySelectorAll("#tform .fg").forEach(g=>{g.classList.remove("bad");const e=g.querySelector(".err");if(e)e.textContent=""});
  live();drawer.classList.add("open");f_task.focus();
}
function closeForm(){drawer.classList.remove("open")}
function setPr(p){fPr=p;f_pr.querySelectorAll("button").forEach(b=>b.classList.toggle("on",b.textContent===p))}
f_pr.onclick=e=>{const b=e.target.closest("button");if(b){setPr(b.textContent);live()}};
f_pctR.oninput=()=>{f_pct.value=f_pctR.value;pctChanged()};
f_pct.oninput=()=>{let v=Math.max(0,Math.min(100,+f_pct.value||0));f_pctR.value=v;pctChanged()};
qpPct.onclick=e=>{const p=e.target.dataset.p;if(p==null)return;f_pct.value=p;f_pctR.value=p;pctChanged()};
qpDue.onclick=e=>{const d=e.target.dataset.d;if(!d)return;const b=dn(f_ad.value)??dn(C.rdS);const x=new Date((b+ +d)*MS);f_due.value=x.toISOString().slice(0,10);live()};
function pctChanged(){if(+f_pct.value>=100&&!f_cd.value){f_cd.value=C.rdS;cdHint.textContent="Completion date set to the report date. Change it if needed."}
  if(+f_pct.value<100&&f_cd.value&&fId!==null&&!fBase.cd){f_cd.value="";cdHint.textContent="Entering a date marks the task Completed (100%)."}live()}
f_cd.oninput=()=>{if(f_cd.value){f_pct.value=100;f_pctR.value=100}live()};
[f_task,f_ad,f_due,f_a1,f_a2,f_a3,f_by].forEach(el=>el.addEventListener("input",live));
tform.addEventListener("input",e=>{const g=e.target.closest(".fg");if(g&&g.classList.contains("bad")){g.classList.remove("bad");g.querySelector(".err").textContent=""}});
f_pr.addEventListener("click",()=>{const g=f_pr.closest(".fg");g.classList.remove("bad");g.querySelector(".err").textContent=""});
function readForm(){return {task:f_task.value.trim(),ad:f_ad.value,by:f_by.value,fn:f_fn.value,due:f_due.value,cd:f_cd.value,a1:f_a1.value,a2:f_a2.value,a3:f_a3.value,pr:fPr,pct:Math.round(Math.max(0,Math.min(100,+f_pct.value||0))),rem:f_rem2.value.trim()}}
function live(){const t=readForm(),rd=dn(C.rdS),due=dn(t.due),done=!!t.cd||t.pct>=100;
  let rem="–",st="";if(t.task){st=done?"Completed":(due!=null&&rd>due)?"Overdue":t.pct===0?"Not Started":"In Progress"}
  if(done)rem="Done";else if(due!=null)rem=(due-rd)+" day"+(Math.abs(due-rd)===1?"":"s")+(due<rd?" (overdue)":"");
  f_rem.textContent=rem;f_rem.className="ro "+(done?"rd-done":due!=null&&due<rd?"rd-neg":due!=null&&due-rd<=3?"rd-amb":"");
  fStatus.innerHTML=st?`<span class="badge b-${st.replace(" ","")}">${st}</span>`:"";}
function validate(t){const E={};
  if(!t.task)E.task="Please enter the task.";
  if(!t.ad)E.ad="Assigned date is required.";
  if(!t.by)E.by="Select who assigned it.";
  if(!t.due)E.due="Tentative completion date is required.";else if(t.ad&&t.due<t.ad)E.due="Can't be before the assigned date.";
  if(!t.a1)E.a1="At least one person is required.";
  if(t.a2&&t.a2===t.a1)E.a2="Same person already selected.";if(t.a3&&(t.a3===t.a1||t.a3===t.a2))E.a3="Same person already selected.";
  if(t.a3&&!t.a2)E.a2="Fill Assigned To 2 before 3.";
  if(!t.pr)E.pr="Choose a priority.";
  if(t.cd&&t.ad&&t.cd<t.ad)E.cd="Can't be before the assigned date.";
  if(t.cd&&t.cd>C.rdS&&!S.reportDate)E.cd="Completion date can't be in the future.";
  document.querySelectorAll("#tform .fg[data-for]").forEach(g=>{const k=g.dataset.for,m=E[k]||"";g.classList.toggle("bad",!!m);g.querySelector(".err").textContent=m});
  const first=Object.keys(E)[0];if(first){const el=fEl("f_"+first);el&&el.focus&&el.focus()}
  return !first}
async function saveForm(again){if(fBusy)return;const t=readForm();if(!validate(t))return;
  fBusy=true;fSave.disabled=fSaveNew.disabled=true;
  try{
    if(fId!==null){const p={};for(const k in t)if(String(t[k])!==String(fBase[k]))p[k]=t[k];
      if(Object.keys(p).length&&!await patchTask(fId,p,"Changes saved."))return;closeForm()}
    else{const r=await run(()=>dbInsert({...t,id:crypto.randomUUID()}));if(!r.ok)return;
      const id=r.v.id;putTask(r.v);undo=()=>run(()=>dbDelete(id));compute();hdr();refreshCurrent();toast(`Task #${S.tasks.findIndex(x=>x.id===id)+1} added.`,true);
      if(again){openForm(null);opts(f_by,S.assigners,t.by,"— Select —");opts(f_fn,S.functions,t.fn,"— Select —");f_ad.value=t.ad}else closeForm()}
  }finally{fBusy=false;fSave.disabled=fSaveNew.disabled=false}}
function refreshCurrent(){const t=(location.hash||"#dashboard").slice(1);if(t==="tracker")renderTracker();else if(t==="dashboard")renderDash();else if(t==="summary")renderSummary();else if(t==="calculation")renderCalc();else if(t==="lists")renderLists();}
fSave.onclick=()=>saveForm(false);fSaveNew.onclick=()=>saveForm(true);tform.onsubmit=e=>{e.preventDefault();saveForm(false)};
fCancel.onclick=closeForm;fX.onclick=closeForm;drawer.onclick=e=>{if(e.target===drawer)closeForm()};
fDel.onclick=()=>askDelete(fId,closeForm);
hdrNew.onclick=()=>openForm(null);
document.addEventListener("keydown",e=>{
  if(e.key==="Escape"){if(confirm_.style.display==="flex"){cNo.click()}else if(drawer.classList.contains("open"))closeForm();else modal.style.display="none"}
  if(drawer.classList.contains("open")&&(e.ctrlKey||e.metaKey)&&e.key==="Enter"){e.preventDefault();saveForm(false)}
  if(e.altKey&&(e.key==="n"||e.key==="N")&&!drawer.classList.contains("open")){e.preventDefault();openForm(null)}
});

// ---------- summary ----------
function renderSummary(){
  const K=C.K;
  document.getElementById("sumNote").textContent=`As of ${fmtLong(C.rdS)}   |   Follows Dashboard filters → Priority: ${F.pri} • Assigned By: ${F.by} • Team Member: ${F.mem} • Job Function: ${F.fn}`;
  const kp=[["Total Tasks",K.total,""],["Completed",K.completed,""],["In Progress",K.inprog,""],["Not Started",K.notst,""],
   ["Overdue",K.overdue,K.overdue>0?'<span class="bad">Action needed</span>':'<span class="good">OK</span>'],
   ["Completion Rate",pc(K.rate,1),K.rate>=.8?'<span class="good">Good</span>':'<span class="bad">Below 80% target</span>'],
   ["Avg. Completion %",pc(K.avg,1),""],["On-Time Delivery Rate",pc(K.ontime,1),K.ontime>=.9?'<span class="good">Good</span>':'<span class="bad">Below 90% target</span>'],
   ["Urgent + High Open",K.crit,""],["Due in Next 7 Days",K.due7,""],["Avg. Days Overdue",K.avgOd.toFixed(1),""],["Avg. Days to Complete",K.avgDays.toFixed(1),""],["Overdue Rate",pc(K.odRate,1),""]];
  const stTot=C.status.reduce((a,s)=>a+s.n,0);
  let h=`<div class="grid2"><div><div class="sec">1. KEY PERFORMANCE INDICATORS</div><table class="sm"><thead><tr><th>Indicator</th><th>Value</th><th>Comment</th></tr></thead><tbody>${kp.map(([a,b,c])=>`<tr><td class="l">${a}</td><td><b>${b}</b></td><td class="cm">${c}</td></tr>`).join("")}</tbody></table></div>
  <div><div class="sec">2. STATUS BREAKDOWN</div><table class="sm"><thead><tr><th>Status</th><th>Tasks</th><th>Share</th></tr></thead><tbody>${C.status.map(s=>`<tr><td class="l"><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:${SCOL[s.s]};margin-right:6px"></span>${s.s}</td><td>${s.n}</td><td>${stTot?pc(s.n/stTot,1):"0.0%"}</td></tr>`).join("")}
  <tr class="tot"><td class="l">Total</td><td>${stTot}</td><td>${stTot?"100.0%":"0.0%"}</td></tr></tbody></table>
  <div class="sec">5. ASSIGNED BY</div><table class="sm"><thead><tr><th>Assigned By</th><th>Total</th><th>Completed</th><th>Overdue</th></tr></thead><tbody>${C.byT.filter(x=>x.n).map(x=>`<tr><td class="l">${esc(x.n)}</td><td>${x.t}</td><td>${x.c}</td><td>${x.od}</td></tr>`).join("")}</tbody></table></div></div>`;
  const pt=STATUSES.map(s=>C.prio.reduce((a,p)=>a+p.by[s],0)),ptT=pt.reduce((a,b)=>a+b,0);
  h+=`<div class="sec">3. PRIORITY × STATUS MATRIX</div><table class="sm"><thead><tr><th>Priority</th>${STATUSES.map(s=>`<th>${s}</th>`).join("")}<th>Total</th><th>Completion Rate</th></tr></thead><tbody>${
   C.prio.map(p=>{const t=STATUSES.reduce((a,s)=>a+p.by[s],0);return `<tr><td class="l p-${p.p}">${p.p}</td>${STATUSES.map(s=>`<td>${p.by[s]}</td>`).join("")}<td><b>${t}</b></td><td>${t?pc(p.by.Completed/t):"0%"}</td></tr>`}).join("")}
   <tr class="tot"><td class="l">Total</td>${pt.map(v=>`<td>${v}</td>`).join("")}<td>${ptT}</td><td>${ptT?pc(pt[0]/ptT):"0%"}</td></tr></tbody></table>`;
  h+=`<div class="sec">4. TEAM MEMBER WORKLOAD</div><table class="sm"><thead><tr><th>Team Member</th><th>Assigned</th><th>Completed</th><th>Open</th><th>Overdue</th><th>Completion Rate</th><th>Avg. Completion %</th></tr></thead><tbody>${
   C.team.filter(x=>x.n).map(x=>`<tr><td class="l">${esc(x.n)}</td><td>${x.a}</td><td>${x.c}</td><td>${x.o}</td><td${x.od?' class="bad"':""}>${x.od}</td><td><div style="display:flex;gap:8px;align-items:center"><div class="minibar" style="flex:1"><span style="width:${x.rate*100}%"></span></div>${pc(x.rate)}</div></td><td>${pc(x.avg)}</td></tr>`).join("")}</tbody></table>`;
  h+=`<div class="sec">6. JOB FUNCTION BREAKDOWN</div><table class="sm"><thead><tr><th>Job Function</th><th>Total</th><th>Completed</th><th>Open</th><th>Overdue</th><th>Completion Rate</th></tr></thead><tbody>${
   C.byFn.filter(x=>x.a||x.n!=="(Not set / other)").map(x=>`<tr><td class="l">${esc(x.n)}</td><td>${x.a}</td><td>${x.c}</td><td>${x.o}</td><td${x.od?' class="bad"':""}>${x.od}</td><td><div style="display:flex;gap:8px;align-items:center"><div class="minibar" style="flex:1"><span style="width:${x.rate*100}%"></span></div>${pc(x.rate)}</div></td></tr>`).join("")}</tbody></table>`;
  h+=`<div class="sec" style="background:#C00000">7. TOP 10 OVERDUE TASKS</div>${overdueTable(10)}`;
  document.getElementById("sumBody").innerHTML=h;
}

// ---------- calculation ----------
function renderCalc(){
  const K=C.K;const kv=(a,b)=>`<tr><td class="l">${esc(a)}</td><td><b>${esc(b)}</b></td></tr>`;
  const t=(title,head,rows)=>`<div class="sec">${title}</div><table class="sm"><thead><tr>${head.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table>`;
  let right=t("SETTINGS",["Item","Value"],kv("Report Date",fmtLong(C.rdS)+(S.reportDate?" (fixed)":" (today)"))+kv("Filter – Priority",F.pri)+kv("Filter – Assigned By",F.by)+kv("Filter – Team Member",F.mem)+kv("Filter – Job Function",F.fn)+kv("Trend Start Month",mLabel(C.months[0])));
  right+=t("KPI CALCULATIONS (filter-aware)",["KPI","Value"],[["Total Tasks",K.total],["Completed",K.completed],["In Progress",K.inprog],["Not Started",K.notst],["Overdue",K.overdue],["Completion Rate",pc(K.rate,1)],["Avg. Completion %",pc(K.avg,1)],["On-Time Delivery Rate",pc(K.ontime,1)],["Urgent + High Open",K.crit],["Due in Next 7 Days",K.due7],["Avg. Days Overdue",K.avgOd.toFixed(1)],["Avg. Days to Complete",K.avgDays.toFixed(1)],["Overdue Rate",pc(K.odRate,1)]].map(x=>kv(...x)).join(""));
  const sT=C.status.reduce((a,s)=>a+s.n,0);
  right+=t("STATUS DISTRIBUTION (Pie chart)",["Status","Tasks","Share"],C.status.map(s=>`<tr><td class="l">${s.s}</td><td>${s.n}</td><td>${sT?pc(s.n/sT,1):"0.0%"}</td></tr>`).join(""));
  right+=t("PRIORITY-WISE (Bar chart)",["Priority","Open","Completed","Total"],C.prio.map(p=>`<tr><td class="l">${p.p}</td><td>${p.open}</td><td>${p.comp}</td><td>${p.total}</td></tr>`).join(""));
  right+=t("MONTHLY TREND – last 12 months (Line chart)",["Month","Assigned","Completed"],C.trend.map(x=>`<tr><td>${mLabel(x.m)}</td><td>${x.a}</td><td>${x.c}</td></tr>`).join(""));
  right+=t("TEAM MEMBER WORKLOAD (Bar chart) – counts Assigned To 1, 2 & 3",["Team Member","Assigned","Completed","Open","Overdue","Completion Rate","Avg. Completion %"],C.team.map(x=>`<tr><td class="l">${esc(x.n)}</td><td>${x.a}</td><td>${x.c}</td><td>${x.o}</td><td>${x.od}</td><td>${pc(x.rate)}</td><td>${pc(x.avg)}</td></tr>`).join(""));
  right+=t("ASSIGNED BY",["Assigned By","Total","Completed","Overdue"],C.byT.map(x=>`<tr><td class="l">${esc(x.n)}</td><td>${x.t}</td><td>${x.c}</td><td>${x.od}</td></tr>`).join(""));
  right+=t("JOB FUNCTION (Bar chart)",["Job Function","Total","Completed","Open","Overdue","Completion Rate"],C.byFn.map(x=>`<tr><td class="l">${esc(x.n)}</td><td>${x.a}</td><td>${x.c}</td><td>${x.o}</td><td>${x.od}</td><td>${pc(x.rate)}</td></tr>`).join(""));
  const left=`<div class="sec" style="background:#2E75B6">ROW-LEVEL HELPERS</div><div class="wrap"><table class="sm"><thead><tr>${["SL","Valid","Due Date","Completed","Status","Days Overdue","On-Time","In Filter","Assigned Month","Completed Month","Completion %","Priority","Job Function","Actual Days Taken"].map(x=>`<th style="background:#2E75B6">${x}</th>`).join("")}</tr></thead><tbody>${
    C.rows.map(r=>`<tr><td>${r.valid?r.i+1:""}</td><td>${r.valid?1:0}</td><td>${r.valid?fmtD(r.t.due):""}</td><td>${r.done?1:0}</td><td>${r.status}</td><td>${r.overdue}</td><td>${r.onTime}</td><td>${r.inF}</td><td>${r.am?mLabel(r.am):""}</td><td>${r.cm?mLabel(r.cm):""}</td><td>${r.cp}%</td><td>${esc(r.t.pr)}</td><td>${esc(r.t.fn)}</td><td>${r.actual}</td></tr>`).join("")}</tbody></table></div>`;
  document.getElementById("calcBody").innerHTML=`<div class="grid2" style="grid-template-columns:1.25fr 1fr"><div>${left}</div><div>${right}</div></div>`;
}

// ---------- lists ----------
const LISTS=[["members","lMem","nMem","team member"],["assigners","lBy","nBy","assigned-by entry"],["functions","lFn","nFn","job function"]];
function renderLists(){
  LISTS.forEach(([k,box,cnt])=>{const el=document.getElementById(box);
    el.innerHTML=LK[k].map((v,i)=>`<div class="lrow"><span class="n">${i+1}</span><input data-k="${k}" data-id="${v.id}" value="${esc(v.name)}" maxlength="120" placeholder="Type a name, then press Enter"><button class="x" data-k="${k}" data-del="${v.id}" title="Remove">✕</button></div>`).join("")||'<div class="note" style="margin:4px 0">No entries yet.</div>';
    document.getElementById(cnt).textContent="("+S[k].length+")"});
  repDate.value=S.reportDate||"";
}
const sLists=document.querySelector("#s-lists");
sLists.addEventListener("keydown",e=>{if(e.key==="Enter"&&e.target.dataset.k)e.target.blur()});
sLists.addEventListener("change",async e=>{const el=e.target,k=el.dataset.k;if(!k)return;const v=el.value.trim(),id=el.dataset.id;
  if(!id){if(!v)return;const r=await run(()=>dbListAdd({kind:k,name:v}));if(r.ok)await refresh(true);return}
  const old=LK[k].find(x=>String(x.id)===id);if(!old)return;
  if(!v){el.value=old.name;toast("Use ✕ to remove an entry.");return}
  el.value=v;if(v===old.name)return;const was=old.name;
  const r=await run(()=>dbListRename(old.id,v));if(!r.ok)return;
  await refresh(true);undo=()=>run(()=>dbListRename(old.id,was));toast(`Renamed “${was}” to “${v}”. Existing tasks keep the old name.`,true)});
sLists.addEventListener("click",async e=>{
  const add=e.target.closest("[data-add]");if(add){const k=add.dataset.add,box=document.getElementById(LISTS.find(x=>x[0]===k)[1]);
    if(!box.querySelector("input:not([data-id])")){box.querySelector(".note")?.remove();box.insertAdjacentHTML("beforeend",`<div class="lrow"><span class="n">+</span><input data-k="${k}" maxlength="120" placeholder="Type a name, then press Enter"></div>`)}
    box.querySelector("input:not([data-id])").focus();return}
  const del=e.target.closest("[data-del]");if(del){const k=del.dataset.k,row=LK[k].find(x=>String(x.id)===del.dataset.del);if(!row)return;
    const r=await run(()=>dbListDelete(row.id));if(!r.ok)return;
    await refresh(true);undo=()=>run(()=>dbListAdd({id:row.id,kind:k,name:row.name}));toast(`Removed “${row.name}”. Existing tasks keep this value.`,true)}});
async function setReport(d){if(d&&!/^\d{4}-\d{2}-\d{2}$/.test(d))return;S.reportDate=d;repDate.value=d;compute();hdr();await run(()=>dbReportDate(d))}
repDate.onchange=()=>setReport(repDate.value);
repClear.onclick=()=>setReport("");
loadSample.onclick=()=>askConfirm("Load sample data?",`All ${S.tasks.length} current tasks will be replaced for everyone by ${SAMPLE.length} sample tasks.`,"Replace",()=>replaceAll({tasks:cleanTasks(SAMPLE)},"Sample data loaded."));
clearAll.onclick=()=>askConfirm("Clear all tasks?",`All ${S.tasks.length} tasks will be removed for everyone. Take a Backup first.`,"Clear all",()=>replaceAll({tasks:[]},"All tasks cleared."));

// ---------- misc ----------
let tt_;function toast(m,canUndo){toastMsg.textContent=m;toastBtn.style.display=canUndo?"":"none";toast_.style.display="flex";clearTimeout(tt_);tt_=setTimeout(()=>toast_.style.display="none",6000)}
const toast_=document.getElementById("toast");
toastBtn.onclick=async()=>{toast_.style.display="none";const f=undo;undo=null;if(f){const r=await f();if(r.ok)await refresh(true)}};
function hdr(){document.getElementById("hdrsub").textContent=`Report date: ${fmtLong(C.rdS)}   |   Filters → Priority: ${F.pri} • Assigned By: ${F.by} • Team Member: ${F.mem} • Job Function: ${F.fn}`}
["fPri","fBy","fMem","fFn"].forEach((id,k)=>document.getElementById(id).onchange=e=>{F[["pri","by","mem","fn"][k]]=e.target.value;compute();hdr();renderDash()});
fReset.onclick=()=>{F={pri:"All",by:"All",mem:"All",fn:"All"};fillFilters();compute();hdr();renderDash()};
function doPrint(t){document.querySelectorAll("section").forEach(s=>s.classList.toggle("print",s.id==="s-"+t));try{window.print()}catch(e){toast("Printing is blocked in this viewer.")}}
const TABS=["dashboard","tracker","summary","calculation","lists","guide"];
function show(){let t=(location.hash||"#dashboard").slice(1);if(!TABS.includes(t))t="dashboard";if(!loaded)return;
  document.querySelectorAll("nav a").forEach(a=>a.classList.toggle("on",a.dataset.t===t));
  document.querySelectorAll("section").forEach(s=>s.classList.toggle("on",s.id==="s-"+t));
  compute();hdr();
  if(t==="dashboard"){fillFilters();renderDash()}else if(t==="tracker"){dl();renderTracker()}else if(t==="summary")renderSummary();else if(t==="calculation")renderCalc();else if(t==="lists")renderLists();
}
document.querySelectorAll("[data-print]").forEach(b=>b.addEventListener("click",()=>doPrint(b.dataset.print)));
addEventListener("hashchange",show);
boot();
